using UnityEngine;using UnityEngine.Rendering.HighDefinition;
public static class CaptureMower {public static string Main(){var trike=Object.FindFirstObjectByType<LawnmowerController>();var go=new GameObject("Trike preview camera"){hideFlags=HideFlags.HideAndDontSave};var camera=go.AddComponent<Camera>();camera.enabled=false;camera.nearClipPlane=.01f;go.AddComponent<HDAdditionalCameraData>();var rt=RenderTexture.GetTemporary(1400,1000,24);var old=RenderTexture.active;var image=new Texture2D(1400,1000,TextureFormat.RGB24,false);try{foreach(bool inside in new[]{false,true}){camera.fieldOfView=inside?70:45;if(inside){go.transform.SetPositionAndRotation(trike.GetComponent<BicycleController>().riderView.position,trike.transform.rotation*Quaternion.Euler(3,0,0));}else{go.transform.position=trike.transform.TransformPoint(new Vector3(-7,5,6));go.transform.LookAt(trike.transform.TransformPoint(new Vector3(0,1,-2)));}camera.targetTexture=rt;camera.Render();camera.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1400,1000),0,0);image.Apply();System.IO.File.WriteAllBytes("output/Lawnmower/"+(inside?"DriverView":"Exterior")+".png",image.EncodeToPNG());}return "Captured exterior and driver view";}finally{camera.targetTexture=null;RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);Object.DestroyImmediate(image);Object.DestroyImmediate(go);}}}

